{
  "explanation": "The functions eˣ and ln(x) are inverses of each other, which means reflecting the graph of one across the line y = x produces the other. Geometrically, every point (a, b) on y = eˣ maps to (b, a) on y = ln(x), and vice versa. Drag the yellow point along either curve to see its reflection land on the other curve.",
  "manimCode": "const ax = new Axes({
  xRange: [-3, 5, 1],
  yRange: [-3, 5, 1],
  xLength: 7,
  yLength: 7,
  tips: true
});
ax.moveTo([0, 0, 0]);

const expCurve = ax.plot(x => Math.exp(x), { color: BLUE, xRange: [-3, 1.6] });
const lnCurve = ax.plot(x => Math.log(x), { color: GREEN, xRange: [0.05, 5] });
const yEqualsX = ax.plot(x => x, { color: GRAY, xRange: [-3, 5] });
yEqualsX.setStrokeWidth(1.5);

const expLabel = new MathTex({ latex: 'e^x', color: BLUE });
await expLabel.waitForRender();
expLabel.moveTo(ax.c2p(1.2, 3.2));
expLabel.scale(0.7);

const lnLabel = new MathTex({ latex: '\\ln(x)', color: GREEN });
await lnLabel.waitForRender();
lnLabel.moveTo(ax.c2p(3.5, 1.5));
lnLabel.scale(0.7);

const yxLabel = new MathTex({ latex: 'y = x', color: GRAY });
await yxLabel.waitForRender();
yxLabel.moveTo(ax.c2p(3.8, 3.2));
yxLabel.scale(0.55);

// Point on e^x and its reflection on ln(x)
let t = 0.5; // x-value on e^x
const pointExp = new Dot({ point: ax.c2p(t, Math.exp(t)), color: YELLOW });
const pointLn = new Dot({ point: ax.c2p(Math.exp(t), t), color: ORANGE });

// Dashed connector (reflection line segment across y=x)
const connector = new Polygon({
  vertices: [ax.c2p(t, Math.exp(t)), ax.c2p(Math.exp(t), t)],
  color: YELLOW_A
});
connector.setStrokeWidth(1.5).setFillOpacity(0);

// Labels for the points
let coordExp = new Text({ text: '(' + t.toFixed(1) + ', ' + Math.exp(t).toFixed(1) + ')', color: YELLOW, fontSize: 18 });
coordExp.moveTo(ax.c2p(t, Math.exp(t)));
coordExp.shift(scaleVec(0.45, UL));

let coordLn = new Text({ text: '(' + Math.exp(t).toFixed(1) + ', ' + t.toFixed(1) + ')', color: ORANGE, fontSize: 18 });
coordLn.moveTo(ax.c2p(Math.exp(t), t));
coordLn.shift(scaleVec(0.45, DR));

scene.add(ax, expCurve, lnCurve, yEqualsX, expLabel, lnLabel, yxLabel);
scene.add(connector, pointExp, pointLn, coordExp, coordLn);

function refresh() {
  const px = t;
  const py = Math.exp(t);
  pointExp.moveTo(ax.c2p(px, py));
  pointLn.moveTo(ax.c2p(py, px));
  connector.setVertices([ax.c2p(px, py), ax.c2p(py, px)]);

  const posE = coordExp.getCenter();
  scene.remove(coordExp);
  coordExp = new Text({ text: '(' + px.toFixed(2) + ', ' + py.toFixed(2) + ')', color: YELLOW, fontSize: 18 });
  coordExp.moveTo(ax.c2p(px, py));
  coordExp.shift(scaleVec(0.45, UL));
  scene.add(coordExp);

  scene.remove(coordLn);
  coordLn = new Text({ text: '(' + py.toFixed(2) + ', ' + px.toFixed(2) + ')', color: ORANGE, fontSize: 18 });
  coordLn.moveTo(ax.c2p(py, px));
  coordLn.shift(scaleVec(0.45, DR));
  scene.add(coordLn);
}

const controls = new Controls(scene, { position: 'bottom-left', width: 260 });
controls.addSlider({
  label: 'x on eˣ',
  min: -1.5,
  max: 1.5,
  value: 0.5,
  step: 0.05,
  onChange: (val) => {
    t = val;
    refresh();
  }
});

controls.addButton({
  label: 'Reset',
  onClick: () => {
    t = 0.5;
    refresh();
  }
});

await scene.wait(999999);"
